import React, { useState } from "react";
import { Terminal, Trash2, ShieldAlert, Cpu, CheckCircle2, Loader2, AlertCircle } from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface OperationsPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function OperationsPanel({ api, getAuthHeaders, triggerToast }: OperationsPanelProps) {
  // Rate-limiting / Debounce timers (10 seconds)
  const [cacheClearDebounce, setCacheClearDebounce] = useState(false);
  const [diagnosticsDebounce, setDiagnosticsDebounce] = useState(false);

  // States
  const [loadingCache, setLoadingCache] = useState(false);
  const [loadingDiagnostics, setLoadingDiagnostics] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [showLogs, setShowLogs] = useState(false);

  const handleClearCache = async (type: "L1" | "L2" | "both") => {
    if (cacheClearDebounce) {
      triggerToast("Cache clear operation rate-limited. Please wait 10 seconds between operations.", "info");
      return;
    }

    if (!window.confirm(`Are you sure you want to clear ${type} Cache? Clearing caches may cause a temporary increase in API latencies.`)) {
      return;
    }

    setLoadingCache(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/cache/clear`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ type })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast(json.message || `Successfully cleared ${type} cache.`, "success");
        // Start 10-second debounce
        setCacheClearDebounce(true);
        setTimeout(() => setCacheClearDebounce(false), 10000);
      } else {
        triggerToast(json.error || "Failed to clear cache", "error");
      }
    } catch {
      triggerToast("Network error clearing cache", "error");
    } finally {
      setLoadingCache(false);
    }
  };

  const handleFetchDiagnostics = async () => {
    if (diagnosticsDebounce) {
      triggerToast("Diagnostics generation rate-limited. Please wait 10 seconds.", "info");
      return;
    }

    setLoadingDiagnostics(true);
    try {
      const res = await fetchWithAuth(`${api}/api/admin/diagnostics`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success) {
        setLogs(json.logs || []);
        setShowLogs(true);
        triggerToast("Diagnostic records retrieved successfully.", "success");
        // Start 10-second debounce
        setDiagnosticsDebounce(true);
        setTimeout(() => setDiagnosticsDebounce(false), 10000);
      } else {
        triggerToast(json.error || "Failed to retrieve diagnostics", "error");
      }
    } catch {
      triggerToast("Network error loading diagnostics logs", "error");
    } finally {
      setLoadingDiagnostics(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold text-main flex items-center gap-2">
            <Cpu className="text-indigo-400" /> Administrative Operations Panel
          </h2>
          <p className="text-xs text-secondary">Execute infrastructure actions and run health checks.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* L1/L2 Cache Flushing Box */}
        <div className="bg-card border border-subtle rounded-xl p-5 space-y-4 lg:col-span-2 shadow-sm">
          <h3 className="text-sm font-bold text-main flex items-center gap-2">
            <Trash2 size={16} className="text-indigo-400" /> Cache Invalidation Tools
          </h3>
          <p className="text-xs text-secondary leading-relaxed">
            Evict memory entries across L1 NodeCache cluster nodes or L2 Upstash Redis synchronization channels. This action forces real-time query reload on subsequent passenger searches.
          </p>
 
          <div className="flex flex-wrap gap-3 pt-2">
            <button onClick={() => handleClearCache("L1")} disabled={loadingCache || cacheClearDebounce}
              className="px-4 py-2 bg-input hover:bg-card text-secondary hover:text-main border border-subtle rounded-lg text-xs font-semibold transition disabled:opacity-40 flex items-center gap-1.5">
              {loadingCache && <Loader2 size={12} className="animate-spin" />} Clear L1 Cache
            </button>
            <button onClick={() => handleClearCache("L2")} disabled={loadingCache || cacheClearDebounce}
              className="px-4 py-2 bg-input hover:bg-card text-secondary hover:text-main border border-subtle rounded-lg text-xs font-semibold transition disabled:opacity-40 flex items-center gap-1.5">
              {loadingCache && <Loader2 size={12} className="animate-spin" />} Clear L2 Cache
            </button>
            <button onClick={() => handleClearCache("both")} disabled={loadingCache || cacheClearDebounce}
              className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-xs font-bold transition disabled:opacity-40 flex items-center gap-1.5">
              {loadingCache && <Loader2 size={12} className="animate-spin" />} Flush All Caches
            </button>
          </div>
          {cacheClearDebounce && (
            <p className="text-[10px] text-yellow-600 dark:text-yellow-400 flex items-center gap-1 font-semibold">
              <AlertCircle size={10} /> Rate limit active. Debounce timer will release button in 10s.
            </p>
          )}
        </div>

        {/* Safeguards / Prohibited Actions Box */}
        <div className="bg-card border border-red-955/20 dark:border-red-900/30 rounded-xl p-5 space-y-4 shadow-sm">
          <h3 className="text-sm font-bold text-red-650 dark:text-red-400 flex items-center gap-2">
            <ShieldAlert size={16} /> Operations Safeguards
          </h3>
          <ul className="text-xs text-secondary space-y-2.5 list-disc pl-4">
            <li>Database drops and migrations are strictly locked to GitHub actions.</li>
            <li>Destructive user drops are disabled; use bulk blocks or session termination instead.</li>
            <li>Global cache clear has a strict 10-second debounce to prevent Redis request spikes.</li>
            <li>Secret reveals are mapped to administrator IP addresses in security audit logs.</li>
          </ul>
        </div>
      </div>

      {/* Diagnostics Logs Box */}
      <div className="bg-card border border-subtle rounded-xl p-5 space-y-4 shadow-sm">
        <div className="flex justify-between items-center">
          <h3 className="text-sm font-bold text-main flex items-center gap-2">
            <Terminal size={16} className="text-indigo-400" /> Daily Server Error Diagnostics
          </h3>
          <button onClick={handleFetchDiagnostics} disabled={loadingDiagnostics || diagnosticsDebounce}
            className="px-4 py-2 bg-input hover:bg-card text-secondary hover:text-main border border-subtle rounded-lg text-xs font-semibold transition disabled:opacity-40 flex items-center gap-1.5">
            {loadingDiagnostics ? <Loader2 size={12} className="animate-spin" /> : <CheckCircle2 size={12} />}
            Run System Diagnostics
          </button>
        </div>
        <p className="text-xs text-secondary leading-relaxed">
          Retrieves the last 100 server-side error events from files recorded under <code className="bg-input border border-subtle px-1.5 py-0.5 rounded text-indigo-600 dark:text-indigo-400">/logs</code> directory.
        </p>
 
        {showLogs && (
          <div className="mt-4 bg-input border border-subtle rounded-lg p-4 font-mono text-xs overflow-hidden">
            <div className="flex justify-between items-center text-[10px] text-muted mb-2 border-b border-subtle pb-2">
              <span>Terminal logs (Last 100 Lines)</span>
              <button onClick={() => setShowLogs(false)} className="hover:text-main">✕ Close</button>
            </div>
            <div className="max-h-60 overflow-y-auto space-y-1 scrollbar-thin select-text">
              {logs.length === 0 ? (
                <div className="text-muted italic">No diagnostics events logged today.</div>
              ) : (
                logs.map((log, index) => (
                  <div key={index} className="text-red-655 dark:text-red-400/90 whitespace-pre-wrap hover:bg-card px-1 py-0.5 rounded">
                    {log}
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {diagnosticsDebounce && (
          <p className="text-[10px] text-yellow-600 dark:text-yellow-400 flex items-center gap-1 font-semibold">
            <AlertCircle size={10} /> Rate limit active. Debounce timer will release button in 10s.
          </p>
        )}
      </div>
    </div>
  );
}
